package com.gr4nt.filexplorer;
import java.io.*;import java.nio.file.*;import java.nio.charset.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.zip.*;
public class CoreTest {
 static int checks;static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}interface Call{void run()throws Exception;}static void fails(Call c,String why)throws Exception{boolean failed=false;try{c.run();}catch(Exception e){failed=true;}check(failed,why);}
 public static void main(String[] args)throws Exception{
  File root=Files.createTempDirectory("fx-tests").toFile(),source=new File(root,"Source");source.mkdir();File sub=new File(source,"nested");sub.mkdir();Files.write(new File(sub,"résumé.txt").toPath(),"A searchable résumé\nNeedle in a document\n".getBytes(StandardCharsets.UTF_8));Files.write(new File(source,"empty.txt").toPath(),new byte[0]);new File(source,"empty-dir").mkdir();File content=new File(source,"中文.txt");Files.write(content.toPath(),"Unicode survives".getBytes(StandardCharsets.UTF_8));
  fails(()->FileSafety.child(root,"../escape"),"Reject traversal");fails(()->FileSafety.child(root,"/absolute"),"Reject absolute path");fails(()->FileSafety.child(root,"C:\\escape"),"Reject Windows absolute path");fails(()->FileSafety.rejectDescendant(source,new File(sub,"archive.zip")),"Reject copy into source");
  File outDir=new File(root,"escape-check");outDir.mkdir();Path link=new File(outDir,"link").toPath();Files.createSymbolicLink(link,root.toPath());fails(()->FileSafety.child(outDir,"link/evil"),"Reject symlink traversal");
  for(String format:new String[]{"zip","7z","tar","tar.gz","tar.xz","tar.bz2","iso"}){
   File archive=new File(root,"roundtrip."+format);Archives.create(archive,Collections.singletonList(source),format,"",new AtomicBoolean());List<Archives.Entry> list=Archives.list(archive,"",new AtomicBoolean());check(list.stream().anyMatch(e->e.name.equals("Source/nested/résumé.txt")),format+" Unicode entry");File dest=new File(root,"out-"+format);Archives.extract(archive,dest,"",new AtomicBoolean());check(Arrays.equals(Files.readAllBytes(new File(dest,"Source/nested/résumé.txt").toPath()),Files.readAllBytes(new File(sub,"résumé.txt").toPath())),format+" bytes");check(new File(dest,"Source/empty-dir").isDirectory(),format+" empty directory");File preview=new File(root,"preview-"+format);Archives.readEntry(archive,"Source/中文.txt",preview,"",new AtomicBoolean());check(Files.readString(preview.toPath()).equals("Unicode survives"),format+" selective read");Archives.verify(archive,"",new AtomicBoolean());check(true,format+" integrity");
  }
  File encrypted=new File(root,"encrypted.zip");Archives.create(encrypted,Collections.singletonList(content),"zip","S3cret 🗝",new AtomicBoolean());File decrypted=new File(root,"decrypted");Archives.extract(encrypted,decrypted,"S3cret 🗝",new AtomicBoolean());check(Files.readString(new File(decrypted,"中文.txt").toPath()).equals("Unicode survives"),"AES-256 ZIP round trip");fails(()->Archives.extract(encrypted,new File(root,"wrong"),"wrong",new AtomicBoolean()),"Reject wrong ZIP password");
  File zip=new File(root,"roundtrip.zip");File replacement=new File(root,"replacement");Files.writeString(replacement.toPath(),"replacement");Archives.replaceZipEntry(zip,"replacement.txt",replacement,"");check(Archives.list(zip,"",new AtomicBoolean()).stream().anyMatch(e->e.name.equals("replacement.txt")),"ZIP entry added");Archives.removeZipEntry(zip,"replacement.txt","");check(Archives.list(zip,"",new AtomicBoolean()).stream().noneMatch(e->e.name.equals("replacement.txt")),"ZIP entry removed");
  File evil=new File(root,"evil.zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(evil))){z.putNextEntry(new ZipEntry("../escaped.txt"));z.write(1);z.closeEntry();}fails(()->Archives.extract(evil,new File(root,"evil-out"),"",new AtomicBoolean()),"ZIP Slip rejected");check(!new File(root,"escaped.txt").exists(),"No escaped file written");
  AtomicBoolean cancelled=new AtomicBoolean(true);fails(()->Archives.create(new File(root,"cancelled.7z"),Collections.singletonList(source),"7z","",cancelled),"Cancelled archive creation");check(!new File(root,"cancelled.7z").exists(),"No cancelled output retained");
  File bin=new File(root,"data.bin");byte[] sec=new byte[2352];Arrays.fill(sec,1,11,(byte)255);sec[15]=1;System.arraycopy("payload".getBytes(StandardCharsets.US_ASCII),0,sec,16,7);Files.write(bin.toPath(),sec);File converted=new File(root,"converted.iso");IsoImage.binToIso(bin,converted,new AtomicBoolean());check(converted.length()==2048&&new String(Files.readAllBytes(converted.toPath()),0,7).equals("payload"),"Raw BIN conversion");Files.write(bin.toPath(),new byte[2352]);fails(()->IsoImage.binToIso(bin,new File(root,"invalid.iso"),new AtomicBoolean()),"Reject arbitrary firmware BIN");
  File exclusive=new File(root,"exclusive");Files.writeString(exclusive.toPath(),"keep");fails(()->FileSafety.newOutput(exclusive),"Exclusive extraction refuses overwrite");check(Files.readString(exclusive.toPath()).equals("keep"),"Existing bytes preserved");
  search(root);
  File smaliDir=new File(root,"smali-source");smaliDir.mkdir();Files.writeString(new File(smaliDir,"Example.smali").toPath(),".class public Lexample/Test;\n.super Ljava/lang/Object;\n.method public static value()I\n .registers 1\n const/4 v0, 0x3\n return v0\n.end method\n");File dex=new File(root,"classes.dex");ApkWorkshop.assemble(smaliDir,dex);check(ApkWorkshop.dexInfo(dex).contains("Lexample/Test;"),"Smali assembly and DEX index");File disassembled=new File(root,"smali-output");ApkWorkshop.disassemble(dex,disassembled);check(new File(disassembled,"example/Test.smali").isFile(),"DEX disassembly");
   check(Arrays.equals(BinaryTools.unhex("00 FF 0a\n11"),new byte[]{0,(byte)255,10,17}),"Hex parse");fails(()->BinaryTools.unhex("xyz"),"Reject invalid hex");
   List<File> single=Collections.singletonList(new File("/tmp/sample.apk"));check(RootPackageInstaller.commandFor(single).equals("pm install -r '/tmp/sample.apk'"),"Root installer command for APK");
   List<File> split=Arrays.asList(new File("/tmp/base.apk"),new File("/tmp/split'quoted.apk"));String splitCommand=RootPackageInstaller.commandFor(split);check(splitCommand.startsWith("pm install-multiple -r ")&&splitCommand.contains("'/tmp/split'\\''quoted.apk'"),"Root installer command safely quotes split APK paths");
   fails(()->RootPackageInstaller.commandFor(Collections.singletonList(new File("/tmp/not-an-apk.zip"))),"Root installer rejects non-APK paths");
   System.out.println("PASS: "+checks+" core assertions: archives, ISO, search, regex, cancellation, paths, DEX/smali, checksums, root install command safety.");
 }
 static void search(File root)throws Exception{
  File search=new File(root,"search");search.mkdir();new File(search,"nested").mkdir();Files.writeString(new File(search,"nested/Annual Report.TXT").toPath(),"first\nneedle target\n");Files.writeString(new File(search,".hidden.txt").toPath(),"needle");Files.writeString(new File(search,"old.pdf").toPath(),"pdf");Files.write(new File(search,"utf16.txt").toPath(),"needle utf16".getBytes(StandardCharsets.UTF_16));Files.write(new File(search,"binary.txt").toPath(),new byte[]{0,1,2,3});
  SearchEngine.Backend b=new SearchEngine.Backend(){public List<SearchEngine.Item> children(SearchEngine.Item dir){File[] list=new File(dir.path).listFiles();List<SearchEngine.Item> out=new ArrayList<>();if(list!=null)for(File f:list)out.add(item(f));return out;}public InputStream read(SearchEngine.Item f)throws IOException{return new FileInputStream(f.path);}public String identity(SearchEngine.Item i)throws IOException{return new File(i.path).getCanonicalPath();}};
  SearchEngine.Options o=new SearchEngine.Options();o.query="annual report";List<SearchEngine.Match> results=find(b,search,o);check(results.size()==1,"Case-insensitive multi-token name search");o.caseSensitive=true;check(find(b,search,o).isEmpty(),"Case-sensitive search");o.caseSensitive=false;o.regex=true;o.query="^annual.*\\.txt$";check(find(b,search,o).size()==1,"Regex name search");o.query="";o.regex=false;o.content="needle";results=find(b,search,o);check(results.size()==2,"UTF8 and UTF16 content search, binary/hidden excluded");check(results.stream().anyMatch(m->m.line==2),"Matched content line numbers");o.hidden=true;check(find(b,search,o).size()==3,"Hidden search option");o.content="";o.extensions="pdf";check(find(b,search,o).size()==1,"Extension filter");o.extensions="";o.query="annual";o.recursive=false;check(find(b,search,o).isEmpty(),"Current directory only");o.recursive=true;o.minSize=10000;check(find(b,search,o).isEmpty(),"Size filter");o.minSize=0;o.after=System.currentTimeMillis()+100000;check(find(b,search,o).isEmpty(),"Date filter");o.after=0;o.query="";o.maxResults=1;check(find(b,search,o).size()==1,"Result cap");AtomicBoolean stop=new AtomicBoolean(true);SearchEngine.Stats stats=SearchEngine.run(b,Collections.singletonList(item(search)),o,stop,new SearchEngine.Listener(){public void match(SearchEngine.Match m){}public void progress(SearchEngine.Stats s){}});check(stats.cancelled&&stats.scanned==0,"Immediate search cancellation");SearchEngine.Options multi=new SearchEngine.Options();multi.recursive=false;multi.query="txt";List<SearchEngine.Match> across=new ArrayList<>();SearchEngine.run(b,Arrays.asList(item(search),item(new File(search,"nested"))),multi,new AtomicBoolean(),new SearchEngine.Listener(){public void match(SearchEngine.Match m){across.add(m);}public void progress(SearchEngine.Stats s){}});check(across.stream().anyMatch(m->m.item.name.equals("Annual Report.TXT")),"Current-directory search visits every selected root");
  o.regex=true;o.query="[";fails(()->find(b,search,o),"Invalid regex rejected");o.query="(a+)+$";String text="a".repeat(20000)+"!";long time=System.nanoTime();check(!com.google.re2j.Pattern.compile(o.query).matcher(text).find()&&(System.nanoTime()-time)<1_000_000_000L,"Linear-time regex engine");
 }
 static SearchEngine.Item item(File f){return new SearchEngine.Item(f.getPath(),f.getName(),f.isDirectory(),f.length(),f.lastModified(),f);}
 static List<SearchEngine.Match> find(SearchEngine.Backend b,File root,SearchEngine.Options o)throws Exception{List<SearchEngine.Match> list=new ArrayList<>();SearchEngine.run(b,Collections.singletonList(item(root)),o,new AtomicBoolean(),new SearchEngine.Listener(){public void match(SearchEngine.Match m){list.add(m);}public void progress(SearchEngine.Stats s){}});return list;}
}
